import{_ as o,o as e,c as t,ag as n}from"./chunks/framework.gmyryY1Z.js";const g=JSON.parse('{"title":"架构演进概述","description":"","frontmatter":{},"headers":[],"relativePath":"zh/evolution/index.md","filePath":"zh/evolution/index.md","lastUpdated":null}'),s={name:"zh/evolution/index.md"};function l(r,a,i,p,d,c){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="架构演进概述" tabindex="-1">架构演进概述 <a class="header-anchor" href="#架构演进概述" aria-label="Permalink to &quot;架构演进概述&quot;">​</a></h1><p>Fast Vue3 经历了从 <strong>Polyrepo（单仓库）</strong> 到 <strong>Monorepo（多包仓库）</strong> 的完整架构演进过程。</p><h2 id="演进时间线" tabindex="-1">演进时间线 <a class="header-anchor" href="#演进时间线" aria-label="Permalink to &quot;演进时间线&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2022 ~ 2024          2025.Q1              2025.Q2 ~ 至今</span></span>
<span class="line"><span>────────────        ────────────         ────────────────</span></span>
<span class="line"><span> Polyrepo 阶段        归档阶段              Monorepo 阶段</span></span>
<span class="line"><span> 单仓单应用           polyrepo 分支         main 分支重建</span></span>
<span class="line"><span> Vite + Vue3          保留历史              多应用工程平台</span></span>
<span class="line"><span> 标准化优化           归档完成              5 套 UI 生态</span></span></code></pre></div><h2 id="两套架构并存" tabindex="-1">两套架构并存 <a class="header-anchor" href="#两套架构并存" aria-label="Permalink to &quot;两套架构并存&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分支</th><th>架构</th><th>描述</th></tr></thead><tbody><tr><td><code>polyrepo</code></td><td>Polyrepo</td><td>历史遗留架构，已归档</td></tr><tr><td><code>main</code></td><td>Monorepo</td><td>新架构，持续演进</td></tr></tbody></table><p><code>polyrepo</code> 分支作为历史参考保留，不再接受新功能开发。<code>main</code> 分支承载所有新工作。</p><h2 id="为什么要迁移" tabindex="-1">为什么要迁移 <a class="header-anchor" href="#为什么要迁移" aria-label="Permalink to &quot;为什么要迁移&quot;">​</a></h2><p>Polyrepo 阶段的主要痛点：</p><ol><li><strong>版本碎片化</strong> — 所有依赖版本分散在单个 <code>package.json</code>，难以统一升级</li><li><strong>无法复用</strong> — 如需支持多套 UI，必须复制整个项目</li><li><strong>工程配置重复</strong> — ESLint、TypeScript、Vite 配置每次都要重写</li><li><strong>缺乏包边界</strong> — 所有代码在 <code>src/</code> 下混合，职责不清晰</li><li><strong>可扩展性差</strong> — 添加新的技术方案需要分叉仓库</li></ol><p>Monorepo 解决的核心问题：</p><ul><li><strong>统一版本管理</strong> — pnpm workspace catalog</li><li><strong>共享基础设施</strong> — <code>packages/*</code> 一次编写，所有应用复用</li><li><strong>可扩展性</strong> — 新增 UI 生态只需 <code>apps/</code> 下新增一个应用</li><li><strong>清晰边界</strong> — 每个包职责单一，接口明确</li></ul><h2 id="本章内容" tabindex="-1">本章内容 <a class="header-anchor" href="#本章内容" aria-label="Permalink to &quot;本章内容&quot;">​</a></h2><div class="vp-doc"><ul><li><a href="./polyrepo">Polyrepo 历史架构</a> — 原始架构分析、技术债务、优化过程</li><li><a href="./monorepo">Monorepo 新架构</a> — 新架构设计、包分割策略、关键决策</li><li><a href="./comparison">架构对比分析</a> — 两种架构的优缺点对比、适用场景</li></ul></div>`,14)])])}const u=o(s,[["render",l]]);export{g as __pageData,u as default};
